import type { CoverageDocument } from './coverage';
import { api } from './client';
import { toListPage, type ListPage } from './listPage';

/** Assets API — the read-only browse/reason surface over `assets` (ADR 0034, #760). */

/** A suite's latest run outcome — mirrors the backend `RunOutcomeRead`. */
export interface RunOutcome {
import type { CoverageLevel } from './coverage';
import { api } from './client';

/** Suites API — a suite is a named bundle of DQ checks bound to one connection. */

/** Mirrors the backend `SuiteRead` schema. */
import { useCallback, useState } from 'react';
import { App } from 'antd';

import { errorMessage } from '../utils/errors';

/**
 * The `setSubmitting(true)` → `try { … } catch { message.error } finally { setSubmitting(false) }`
 * scaffold that recurred across every mutating form (connection/suite/check save, import.
 */
export function useAsyncAction(errorPrefix = 'Action failed'): {
  run: (action: () => Promise<void>) => Promise<void>;
  loading: boolean;
} {
  const { message } = App.useApp();
  const [loading, setLoading] = useState(false);

  const run = useCallback(
    async (action: () => Promise<void>) => {
      setLoading(true);
      try {
        await action();
      } catch (err) {
        message.error(`${errorPrefix}: ${errorMessage(err)}`);
      } finally {
        setLoading(false);
      }
    },
    [message, errorPrefix],
  );

